effect.shader:
void main(){
    float a=radians(angle);
    vec2 dir=vec2(cos(a),sin(a))*depth;
    vec4 front=texture2DCv(inputImg.texture, acScreenNorm);
    vec4 side=vec4(0.0);
    for(int i=1;i<=16;i++){
        vec2 uv=acScreenNorm - dir*(float(i)/16.0);
        vec4 s=texture2DCv(inputImg.texture, uv);
        if(s.a>0.01 && side.a<0.01){ side=s; side.rgb*=1.0-dark; }
    }
    gl_FragColor = front.a>0.01 ? front : side;
}
